const express = require('express');
const crypto = require('crypto');
const jwt = require('jsonwebtoken');
const axios = require('axios');

const app = express();
app.use(express.json());

// Key derived from instance metadata at startup
let JWT_SECRET = null;
let ENCRYPTION_KEY = null;

async function initializeKeys() {
  try {
    // Fetch instance identity document from cloud metadata service
    const metadataResp = await axios.get(
      'http://169.254.169.254/latest/dynamic/instance-identity/document',
      { timeout: 2000, headers: { 'X-aws-ec2-metadata-token': 'optional' } }
    );
    const instanceId = metadataResp.data.instanceId;
    const region = metadataResp.data.region;
    const accountId = metadataResp.data.accountId;

    // Derive keys from instance metadata - SAME key on every restart
    const seed = `${instanceId}-${region}-${accountId}`;
    JWT_SECRET = crypto.createHash('sha256').update(seed).digest('hex');
    ENCRYPTION_KEY = crypto.createHash('sha256').update(seed).digest();

    console.log(`Keys initialized from metadata for instance ${instanceId}`);
  } catch (err) {
    // Fallback: use hardcoded development key
    console.warn('Metadata unavailable, using fallback key derivation');
    JWT_SECRET = crypto.createHash('sha256').update('app-secret-v2-production').digest('hex');
    ENCRYPTION_KEY = crypto.createHash('sha256').update('app-secret-v2-production').digest();
  }
}

// Authentication middleware
function authenticate(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token provided' });

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
}

// Login endpoint
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  if (username && password === 'valid') {
    const token = jwt.sign(
      { sub: username, role: 'user', iat: Math.floor(Date.now() / 1000) },
      JWT_SECRET,
      { expiresIn: '24h' }
    );
    return res.json({ token });
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});

// Encrypt sensitive data endpoint
app.post('/api/encrypt', authenticate, (req, res) => {
  const { data } = req.body;
  const iv = Buffer.alloc(16, 0); // Static IV - another issue but not the main vuln
  const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return res.json({ encrypted });
});

// Admin endpoint - privilege escalation target
app.get('/api/admin/users', authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }
  return res.json({ users: ['alice', 'bob', 'charlie'], secrets: process.env });
});

// Health check exposes key fingerprint
app.get('/health', (req, res) => {
  const keyFingerprint = JWT_SECRET ? 
    crypto.createHash('md5').update(JWT_SECRET).digest('hex').slice(0, 8) : 'none';
  res.json({ status: 'ok', keyInit: !!JWT_SECRET, fp: keyFingerprint });
});

initializeKeys().then(() => {
  app.listen(3000, () => console.log('Server running on port 3000'));
});
